public class Singleton {
  private static volatile Singleton instance;
  private Singleton() {}
  public static Singleton getInstance() {
    if (instance == null) {
      synchronized (Singleton.class) {
        if (instance == null) instance = new Singleton();
      }
    }
    return instance;
  }
} // Double-checked locking

class Formulario {
  private final String nombre;
  private final String email;
  private Formulario(Builder b) { this.nombre = b.nombre; this.email = b.email; }
  public static class Builder {
    private String nombre; private String email;
    public Builder nombre(String n) { this.nombre = n; return this; }
    public Builder email(String e) { this.email = e; return this; }
    public Formulario build() { return new Formulario(this); }
  }
} // Builder interno con validacion

interface RepositorioFactory {
  Repositorio crearUsuario();
  Repositorio crearProducto();
}
class MongoFactory implements RepositorioFactory {
  public Repositorio crearUsuario() { return new MongoUsuarioRepo(); }
  public Repositorio crearProducto() { return new MongoProductoRepo(); }
} // Abstract Factory

class ProxyCache implements Repositorio {
  private final Repositorio real;
  private final Map<String, Object> cache = new HashMap<>();
  public Object buscar(String id) {
    return cache.computeIfAbsent(id, real::buscar);
  }
} // Proxy con cache

interface ComponenteGrafico {
  void dibujar();
}
class Hoja implements ComponenteGrafico { ... }
class Grupo implements ComponenteGrafico {
  private List<ComponenteGrafico> hijos = new ArrayList<>();
  public void agregar(ComponenteGrafico c) { hijos.add(c); }
  public void dibujar() { hijos.forEach(ComponenteGrafico::dibujar); }
} // Composite

class FormateadorAdapter implements FormateadorExterno {
  private FormateadorInterno interno;
  public String formatear(Datos d) { return interno.procesar(d); }
} // Adapter de objetos

class Notificador {
  private List<Observer> observadores = new ArrayList<>();
  public void agregar(Observer o) { observadores.add(o); }
  public void notificar(String evento) {
    observadores.forEach(o -> o.recibir(evento));
  }
} // Observer simple

abstract class Handler {
  protected Handler siguiente;
  public void setSiguiente(Handler h) { this.siguiente = h; }
  public void manejar(Peticion p) {
    if (siguiente != null) siguiente.manejar(p);
  }
}
class AuthHandler extends Handler {
  public void manejar(Peticion p) {
    if (!p.autenticada()) { log("Rechazada"); return; }
    super.manejar(p);
  }
} // Chain of Responsibility

